/**
 * Location data for the net company pages (/dk1/<net>, /dk2/<net>): the page is about a grid company, and the place it
 * covers is that company's supply area. The Place says what we know and no more: it lies inside the price area (DK1 or
 * DK2), and it contains the cities whose sampled addresses the company served (the city table in _cities.js; the same
 * rule as the page's own "Byer i området" line). A company with no sampled city gets the price area alone.
 *
 * Energistyrelsen's map of the licence boundaries (_net-areas.js, generated by scripts/net-areas.py) is the real
 * geometry. Which of it a page carries is an experiment, one variant per page, because a URL cannot be A/B-tested
 * against itself. Every variant adds ONE thing to the control:
 *   base   the Place described above (the control; no Energistyrelsen data)
 *   box    + geo: a GeoShape box around the whole area (south west north east)
 *   map    + hasMap: the simplified boundary as GeoJSON at /net-areas/<slug>.geojson
 *   shape  + geo: a GeoShape polygon of the largest single ring — only for companies where that ring is at least 95 %
 *          of the area (and no longer than 200 points), so it is the area and not a part of it presented as the whole
 * The three data variants also say where the data is from (isBasedOn, and a visible line, netSourceNote). Read the result
 * per page in Search Console and in the structured-data reports around 2026-11-22 and 2026-12-06; with sixteen pages it
 * tells which markup Google accepts and picks up, not a ranking effect.
 *
 * No address, no LocalBusiness, no invented boundary. The same Place is the page's spatialCoverage and the Organization's
 * areaServed. A leading underscore keeps this file out of Pages' route table.
 */
import { CITY_LOCATION } from './_cities.js';
import { NET_AREAS, NET_AREAS_SOURCE } from './_net-areas.js';

export const NET_ARM = {
  'n1': 'base', 'trefor-ost': 'base', 'noe-net': 'base', 'flow-elnet': 'base',
  'cerius': 'box', 'trefor': 'box', 'elvaerk': 'box', 'lnet': 'box',
  'konstant': 'map', 'nord-energi': 'map', 'rah-net': 'map', 'dinel': 'map',
  'vores-elnet': 'shape', 'radius': 'shape', 'elnet-midt': 'shape', 'ravdex': 'shape',
};
/** The conditions a net company must meet to carry a polygon. */
export const SHAPE_MIN_SHARE = 0.95, SHAPE_MAX_POINTS = 200;

const pts = a => a.join(' ');
const ringText = ring => ring.map(([lat, lng]) => `${lat} ${lng}`).join(' ');

/** `towns` are the CITIES rows this net company serves (netTowns in [[path]].js), `region` the price area's text. */
export function netLocation(area, net, towns, region, pageUrl, meta) {
  const arm = NET_ARM[net.slug] || 'base', A = NET_AREAS[net.slug];
  const coverage = {
    '@type': 'Place',
    name: `${net.name}s forsyningsområde`,
    containedInPlace: { '@type': 'Place', name: region },
  };
  const cities = towns.filter(c => CITY_LOCATION[c.slug]).map(c => {
    const L = CITY_LOCATION[c.slug];
    return {
      '@type': 'City', name: c.name,
      geo: { '@type': 'GeoCoordinates', latitude: L.lat, longitude: L.lng },
      sameAs: [`https://www.wikidata.org/wiki/${L.wikidata}`, `https://da.wikipedia.org/wiki/${encodeURIComponent(L.wikipedia)}`],
    };
  });
  if (cities.length) coverage.containsPlace = cities;
  if (A && arm === 'box') coverage.geo = { '@type': 'GeoShape', box: pts(A.box) };
  if (A && arm === 'map') coverage.hasMap = `https://elpriser.org/net-areas/${net.slug}.geojson`;
  if (A && arm === 'shape') coverage.geo = { '@type': 'GeoShape', polygon: ringText(A.ring) };
  const page = {
    '@context': 'https://schema.org', '@type': 'WebPage', name: meta.title, description: meta.description,
    url: pageUrl, inLanguage: 'da', isPartOf: { '@type': 'WebSite', name: 'elpriser.org', url: 'https://elpriser.org' },
    about: { '@type': 'Organization', name: net.name, globalLocationNumber: net.gln, areaServed: coverage },
    spatialCoverage: coverage,
  };
  if (A && arm !== 'base') page.isBasedOn = { '@type': 'CreativeWork', name: NET_AREAS_SOURCE.name, url: NET_AREAS_SOURCE.url };
  return page;
}

/** The visible source line of the three data variants; '' for the control. */
export function netSourceNote(slug) {
  const arm = NET_ARM[slug];
  if (!arm || arm === 'base' || !NET_AREAS[slug]) return '';
  return `Netselskabets område er hentet fra <a href="${NET_AREAS_SOURCE.url}" class="text-brand-500 underline" rel="noopener">Energistyrelsens kort over netvirksomheder og bevillingsgrænser</a> (${dateDa(NET_AREAS_SOURCE.date)}) og er forenklet.`;
}
const MONTHS = ['januar', 'februar', 'marts', 'april', 'maj', 'juni', 'juli', 'august', 'september', 'oktober', 'november', 'december'];
const dateDa = d => { const [y, m] = d.split('-'); return `${MONTHS[+m - 1]} ${y}`; };

/** The GeoJSON of one net company, or of all of them (slug null): a FeatureCollection with its source stated. null if unknown. */
export function netAreasGeoJSON(nets, slug) {
  const list = slug ? nets.filter(n => n.slug === slug && NET_AREAS[n.slug]) : nets.filter(n => NET_AREAS[n.slug]);
  if (!list.length) return null;
  return {
    type: 'FeatureCollection',
    name: slug ? `${list[0].name} — netområde` : 'Netselskabernes områder',
    attribution: `${NET_AREAS_SOURCE.name} (${NET_AREAS_SOURCE.date}), ${NET_AREAS_SOURCE.url}`,
    note: 'Forenklet (300 m) til orientering — ikke til navigation eller juridisk brug. Det autoritative kort er Energistyrelsens.',
    features: list.map(n => ({
      type: 'Feature',
      properties: { slug: n.slug, name: n.name, gln: n.gln, areaKm2: NET_AREAS[n.slug].areaKm2, parts: NET_AREAS[n.slug].parts },
      geometry: NET_AREAS[n.slug].geometry,
    })),
  };
}
